import React from 'react';
import { C } from '../data';
import FadeIn from './FadeIn';

export default function SectionHeader({ tag, title, subtitle }) {
  return (
    <FadeIn className="text-center mb-16">
      <div
        className="inline-block px-4 py-1 rounded-full text-xs font-bold uppercase tracking-widest mb-4"
        style={{ background: C.goldPale, color: C.gold }}
      >
        {tag}
      </div>
      <h2
        className="text-3xl md:text-4xl font-bold mb-4"
        style={{ color: C.text, fontFamily: "'Playfair Display', Georgia, serif" }}
      >
        {title}
      </h2>
      {subtitle && (
        <p className="text-base max-w-xl mx-auto leading-relaxed" style={{ color: C.muted }}>
          {subtitle}
        </p>
      )}
    </FadeIn>
  );
}
